/* AppReq09Mapper.selectAttdSelfApprvYn */
SELECT N.SELF_ATTD_APPRV_YN
  FROM TB_USER U
  JOIN TB_SITE_NODE N
    ON N.CMPNY_CD = U.CMPNY_CD
   AND N.SITE_CD  = U.SITE_CD
   AND N.NODE_CD  = U.NODE_CD
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.SITE_CD  = #{siteCd}
   AND U.USER_CD  = #{userCd}
 LIMIT 1

/* AppReq09Mapper.selectIsNodeAdmin */
SELECT COUNT(1)
  FROM TB_USER U
  JOIN TB_SITE_NODE N
    ON N.CMPNY_CD = U.CMPNY_CD
   AND N.SITE_CD  = U.SITE_CD
   AND N.NODE_CD  = U.NODE_CD
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.SITE_CD  = #{siteCd}
   AND U.USER_CD  = #{userCd}
   AND (N.MAIN_ADMIN_CD = U.USER_CD OR N.SUB_ADMIN_CD = U.USER_CD)

/* AppReq09Mapper.countValidApprovers */
SELECT COUNT(DISTINCT U.USER_CD)
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.SITE_CD  = #{siteCd}
   AND U.USE_YN   = 'Y'
   AND U.WITHDRAWAL_DATE IS NULL
   AND U.ACCOUNT_STATUS  = '01'
   AND U.AUTH_CD != 'system'
   AND U.USER_CD IN

     #{uc}

mapper.update:
/* AppReq09Mapper.updateReqStatus */
UPDATE TB_USER_ATTD_REQ
   SET REQ_STATUS      = #{reqStatus}
     , PROCESS_USER_CD = #{processUserCd}
     , PROCESS_COMMENT = #{processComment}
     , PROCESS_DATE    = NOW()
     , UPDATE_NO       = #{processUserCd}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND REQ_ID   = #{reqId}
